const TRAINING_INTENTS={lose:'Схуднути',maintain:'Підтримувати форму',muscle:'Наростити м’язи',strength:'Стати сильніше',cardio:'Витривалість',start:'Повернутися до руху'};
const TRAINING_LIKES={mixed:'Поєднувати різне',walking:'Тільки ходьба / легкий рух',strength:'Силові',cardio:'Кардіо'};
const TRAINING_GEAR={none:'Без інвентарю',band:'Стрічка / резинки',dumbbell:'Гантелі',machine:'Тренажери'};
const TRAINING_PLACE={home:'Вдома',gym:'У залі',outdoor:'Надворі'};
const trainingOldScore=trainingScore;
trainingScore=function(p,prefs){
 if(prefs.limitations==='medical')return null;
 if(prefs.likes==='walking'&&!p.items.every(item=>['walk','sidewalk','bike','ellip','treadmill','cycle','mobility','breathing'].includes(item[0])))return null;
 if(prefs.limitations==='unsure'&&!['cardio','start'].includes(p.goal))return null;
 const base=trainingOldScore(p,{...prefs,goal:'form'});if(!base)return null;
 let score=base.score,reasons=[...base.reasons];
 const intent=prefs.goal==='form'?'maintain':prefs.goal;
 if(intent==='lose'||intent==='maintain'){
  if(['strength','cardio'].includes(p.goal))score+=5;
  if(p.goal==='start')score+=prefs.level==='beginner'?3:0;
  reasons.unshift(intent==='lose'?'рух для твоєї цілі без гонитви за «спаленими» калоріями':'для підтримки сили й витривалості');
 }else if(p.goal===intent){score+=8;reasons.unshift('відповідає обраній цілі');}
 else if(intent==='muscle'&&p.goal==='strength')score+=3;
 else if(intent==='start'&&p.goal==='cardio')score+=2;
 if(prefs.likes==='strength')score+=p.goal==='strength'||p.goal==='muscle'?5:-4;
 if(prefs.likes==='cardio')score+=p.goal==='cardio'?5:-4;
 if(prefs.level==='beginner'&&p.level==='all')score-=2;
 if(p.minutes>Number(prefs.time))score-=Math.ceil((p.minutes-Number(prefs.time))/5)*2;
 return{plan:p,score,reasons};
};

function trainingOptions(options,value){return options.map(([id,label])=>'<option value="'+id+'" '+(String(value)===String(id)?'selected':'')+'>'+label+'</option>').join('');}
function trainingWizardField(label,key,options){return '<label>'+label+'<select data-wizard="'+key+'">'+trainingOptions(options,trainingWizard[key])+'</select></label>';}
let trainingWizardStep=0,trainingWizard={};
function trainingWizardOpen(){trainingWizardStep=0;trainingWizard={...trainingPrefs,goal:trainingPrefs.goal==='form'?'maintain':trainingPrefs.goal};trainingWizardRender();}
function trainingWizardRender(){let fields='',title='',intro='';
 if(trainingWizardStep===0){title='Що ти хочеш від руху?';intro='Ціль і те, що тобі справді подобається. Не змушуємо бігати, якщо хочеться лише ходити.';fields=trainingWizardField('Моя ціль','goal',Object.entries(TRAINING_INTENTS))+trainingWizardField('Що я люблю','likes',Object.entries(TRAINING_LIKES));}
 if(trainingWizardStep===1){title='Де й скільки зручно?';intro='Зал, дім або прогулянки. Час і кількість днів можна змінити в будь-який момент.';fields=trainingWizardField('Де тренуватись','place',Object.entries(TRAINING_PLACE))+trainingWizardField('Інвентар','gear',Object.entries(TRAINING_GEAR))+trainingWizardField('Мій досвід','level',[['beginner','Починаю / повертаюсь'],['regular','Тренуюсь регулярно']])+trainingWizardField('Час на сесію','time',[[15,'15 хв'],[20,'20 хв'],[30,'30 хв'],[45,'45 хв'],[60,'60 хв']])+trainingWizardField('Днів на тиждень','frequency',[[2,'2 дні'],[3,'3 дні'],[4,'4 дні'],[5,'5 днів']]);}
 if(trainingWizardStep===2){title='Що врахувати для безпеки?';intro='Не треба описувати діагноз. Якщо є обмеження, застосунок не буде «призначати» навантаження автоматично.';fields=trainingWizardField('Самопочуття / обмеження','limitations',[['none','Немає відомих обмежень'],['unsure','Не впевнена / не впевнений або повертаюся після паузи'],['medical','Травма, вагітність, захворювання чи інше медичне обмеження']])+'<p class="training-wizard-note">Це не медичний опитувальник. За незвичних симптомів припини вправу. За медичних обмежень погодь план із лікарем або фізичним терапевтом.</p>';}
 openModal('DAYMARK TRAINING / НАЛАШТУВАННЯ '+(trainingWizardStep+1)+'/3','<div class="training-wizard"><div class="training-wizard-count">0'+(trainingWizardStep+1)+' / 03 <span>🏋️ ТВІЙ ПЛАН</span></div><h2>'+title+'</h2><p>'+intro+'</p><div class="training-wizard-fields">'+fields+'</div><div class="training-wizard-actions">'+(trainingWizardStep?'<button data-action="training-wizard-back">← Назад</button>':'')+'<button class="training-wizard-next" data-action="training-wizard-next">'+(trainingWizardStep===2?'Зберегти мій план ✓':'Далі →')+'</button></div></div>');}
function trainingWizardCollect(){document.querySelectorAll('[data-wizard]').forEach(el=>{const k=el.dataset.wizard;trainingWizard[k]=['time','frequency'].includes(k)?Number(el.value):el.value;});}
actions['training-setup']=trainingWizardOpen;
actions['training-wizard-back']=()=>{trainingWizardCollect();trainingWizardStep=Math.max(0,trainingWizardStep-1);trainingWizardRender();};
actions['training-wizard-next']=()=>{trainingWizardCollect();if(trainingWizardStep<2){trainingWizardStep++;trainingWizardRender();return;}Object.assign(trainingPrefs,trainingWizard,{setup:true,energy:'okay'});if(trainingPrefs.place==='outdoor')trainingPrefs.gear='none';if(trainingPrefs.place==='gym'&&trainingPrefs.gear==='none')trainingPrefs.gear='machine';try{localStorage.setItem(TRAINING_PREF_KEY,JSON.stringify(trainingPrefs));}catch{}closeModal();render();toast('Твої вподобання збережені. План тижня оновлено.');};

const TRAINING_WEEK_KEY='daymark-training-week-v1';
function trainingWeek(){if(!trainingPrefs.setup||trainingPrefs.limitations==='medical')return[];const signature=JSON.stringify(['goal','likes','place','gear','level','time','frequency','limitations'].map(k=>trainingPrefs[k]));try{const saved=JSON.parse(localStorage.getItem(TRAINING_WEEK_KEY));if(saved?.signature===signature&&saved.start<=today()&&diff(saved.start,today())<7&&Array.isArray(saved.slots)&&saved.slots.length===Number(trainingPrefs.frequency)&&saved.slots.every(s=>validDate(s.date)&&trainingPlan(s.id)))return saved.slots.map(s=>({date:s.date,plan:trainingPlan(s.id),score:0,reasons:[]}));}catch{}
 let scored=TRAINING_PLANS.map(p=>trainingScore(p,trainingPrefs)).filter(Boolean).sort((a,b)=>b.score-a.score||a.plan.minutes-b.plan.minutes);if(!scored.length)return[];
 const freq=Number(trainingPrefs.frequency),days=freq===0?[]:freq===1?[0]:freq===2?[0,3]:freq===3?[0,2,4]:freq===4?[0,2,4,6]:[0,1,3,4,6];const used=new Set(),sequence=[];
 days.forEach((day,i)=>{let wanted=trainingPrefs.likes==='walking'?'cardio':trainingPrefs.likes==='cardio'?'cardio':trainingPrefs.goal==='muscle'||trainingPrefs.likes==='strength'?(i%3===2?'cardio':'strength'):(i%3===1?'cardio':'strength');let candidates=scored.filter(s=>!used.has(s.plan.id));if(wanted==='strength')candidates=candidates.filter(s=>['strength','muscle','start'].includes(s.plan.goal));else candidates=candidates.filter(s=>['cardio','start'].includes(s.plan.goal));if(!candidates.length)candidates=scored.filter(s=>!used.has(s.plan.id));const chosen=candidates[0]||scored[i%scored.length];used.add(chosen.plan.id);sequence.push({day,date:offset(today(),day),...chosen});});try{localStorage.setItem(TRAINING_WEEK_KEY,JSON.stringify({start:today(),signature,slots:sequence.map(s=>({date:s.date,id:s.plan.id}))}));}catch{}return sequence;}
function trainingWeeklyPanel(){const week=trainingWeek(),hasLimits=trainingPrefs.limitations==='medical',intent=TRAINING_INTENTS[trainingPrefs.goal]||TRAINING_INTENTS.maintain;
 return '<section class="training-route"><div class="training-route-head"><div><span>ТВІЙ РУХ / НАСТУПНІ 7 ДНІВ</span><h3>'+(trainingPrefs.setup?'План, що підлаштовується.':'Почнемо з тебе.')+'</h3><p>'+(trainingPrefs.setup?intent+' · '+TRAINING_PLACE[trainingPrefs.place]+' · '+trainingPrefs.frequency+' дні/тиждень':'Дай відповіді на кілька питань — зберемо тиждень із тренувань, які реально хочеться робити.')+'</p></div><span class="training-route-mark">🏋️</span></div><button class="training-route-setup" data-action="training-setup">'+(trainingPrefs.setup?'Змінити ціль і вподобання ↗':'Налаштувати мій рух →')+'</button>'+(hasLimits?'<div class="training-route-caution"><b>План не призначено автоматично.</b><p>Ти відзначила / відзначив медичні обмеження. Погодь допустиме навантаження з фахівцем. Після цього можна обрати знайому вправу вручну; застосунок не знає твоїх протипоказань.</p></div>':week.length?'<div class="training-route-week">'+week.map((w,i)=>{const completed=state.logs[w.date]?.workouts?.some(x=>x.programId===w.plan.id);return '<button data-action="training-open" data-id="'+w.plan.id+'" class="training-route-day"><span class="training-route-number">0'+(i+1)+'</span><span><small>'+new Intl.DateTimeFormat('uk-UA',{weekday:'long',day:'numeric',month:'short',timeZone:'UTC'}).format(dt(w.date))+' · '+w.plan.minutes+' хв</small><strong>'+w.plan.name+'</strong><em>'+(completed?'✓ Записано у щоденник':w.plan.tag)+' · '+trainingLabels.place[w.plan.place]+'</em></span><b>↗</b></button>';}).join('')+'</div><p class="training-route-foot">Між сесіями — відновлення або комфортний рух. План не змінюється посеред тижня; наступний врахує записи. Це приклад, не медичне призначення.</p>':trainingPrefs.setup?'<p class="training-route-foot">Під ці параметри поки немає готової комбінації. Зміни місце або інвентар.</p>':'')+'</section>';}

trainingCoachPanel=function(){const paused=trainingRun?.paused;return trainingWeeklyPanel()+(paused?'<button class="training-resume" data-action="training-flow-resume">▶ Продовжити незавершене тренування <b>↗</b></button><button class="training-discard" data-action="training-flow-discard">Скасувати незавершене тренування</button>':'')+'<section class="training-guide-links"><button data-action="plan"><span>01 / ХАРЧУВАННЯ</span><strong>Мій орієнтир калорій і БЖВ</strong><small>'+(typeof dayEnergy==='function'&&dayEnergy().target?num(dayEnergy().target)+' ккал на цей день, разом із рухом':'Один план для всього додатка')+'</small><b>↗</b></button><button data-view="recipes"><span>02 / ІДЕЇ ЇЖІ</span><strong>Що приготувати цього тижня?</strong><small>Страви під ту саму цифру, що й день.</small><b>↗</b></button></section>';};

const priorTrainingStudio=trainingStudio;
trainingStudio=function(){let html=priorTrainingStudio();html=html.replace('<div class="training-filter-group">','<div class="training-zone-title"><b>БІБЛІОТЕКА / '+TRAINING_PLANS.length+' ПРОГРАМИ</b><p>Силові вдома й у залі, кардіозона та маршрути надворі. Фільтруй і відкривай повну послідовність.</p></div><div class="training-filter-group">').replace('15–48 хв','15–60 хв');return html;};
sportHomeCard=function(){return '<button class="sport-home-card" data-action="training-home"><span class="sport-home-icon">'+dumbbellArt()+'</span><span><small>DAYMARK TRAINING · '+TRAINING_PLANS.length+' ПРОГРАМИ</small><strong>Твій план руху на тиждень</strong><em>Побажання, тренування й інтерактивний плеєр</em></span><b>↗</b></button>';};

Object.assign(TRAINING_EXERCISES.legpress,{machine:'Жим ногами — налаштуй сидіння, платформу й фіксатори. Попроси працівника залу показати механізм перед першою спробою.'});
Object.assign(TRAINING_EXERCISES.lat,{machine:'Верхній блок — налаштуй висоту сидіння й валик для ніг; обери легку вагу для знайомства.'});
Object.assign(TRAINING_EXERCISES.chest,{machine:'Жим від грудей — руків’я приблизно на рівні середини грудей. Налаштуй сидіння й вагу.'});
Object.assign(TRAINING_EXERCISES.hamcurl,{machine:'Згинання ніг — відрегулюй сидіння й валик, не працюй через дискомфорт у коліні.'});
Object.assign(TRAINING_EXERCISES.treadmill,{machine:'Доріжка — спершу знайди кнопку зупинки й аварійний ключ. Почни з повільної ходьби; нахил необов’язковий.'});
Object.assign(TRAINING_EXERCISES.bike,{machine:'Велотренажер — налаштуй сидіння, щоб педалі оберталися комфортно; почни з легкого опору.'});

trainingFigure=function(pose){return '<div class="motion-demo pose-'+(Object.hasOwn({squat:1,hinge:1,push:1,pull:1,lunge:1,bridge:1,core:1,step:1,walk:1},pose)?pose:'walk')+'" role="img" aria-label="Анімована об’ємна схема руху; не є точною 3D-демонстрацією техніки"><div class="motion-halo"></div><div class="motion-scene"><div class="motion-stage"></div><div class="motion-avatar"><i class="m-head"></i><i class="m-neck"></i><i class="m-torso"></i><i class="m-pelvis"></i><i class="m-limb m-arm left"></i><i class="m-limb m-arm right"></i><i class="m-limb m-leg left"></i><i class="m-limb m-leg right"></i></div><span class="motion-cue top">● КОНТРОЛЬ РУХУ</span><span class="motion-cue bottom">↗ СПОКІЙНИЙ ТЕМП</span></div><small>Об’ємна анімована схема · орієнтир напрямку, не заміна тренера</small></div>';};
const priorTrainingOpen=trainingOpen;
trainingOpen=function(id){priorTrainingOpen(id);const p=trainingPlan(id);if(!p)return;const e=$('modalBody');e.innerHTML=e.innerHTML.replace('Схеми руху — 2D-ескізи, не 3D-інструкція; перевір техніку з тренером, якщо не впевнений / не впевнена.','У плеєрі буде анімована об’ємна схема та короткі підказки. Вона показує напрямок руху, але не перевіряє твою техніку.').replace(p.items.length+' вправи · розминка 5 хв',p.items.length+' етапи · '+(trainingTimedStages(p)?'легкий старт у програмі':'розминка 5 хв'));};
const priorTrainingExercise=trainingExercise;
trainingExercise=function(id,planId){priorTrainingExercise(id,planId);const e=$('modalBody');e.innerHTML=e.innerHTML.replace('Схема показує напрямок, але не замінює точну демонстрацію техніки. 3D-інструкції з перевіреними ракурсами — наступний етап.','Анімована об’ємна схема ілюструє напрямок. Вона не перевіряє положення суглобів; для складної техніки попроси тренера показати вправу.');};

trainingFlowRender=function(){const r=trainingRun,p=trainingPlan(r?.id);if(!r||!p)return;const item=p.items[r.index],x=item&&TRAINING_EXERCISES[item[0]],total=trainingTotalSets(p),count=item?trainingSetCount(item):1,target=item?trainingTargetSeconds(item):0,progress=Math.min(100,Math.round(r.done/Math.max(total,1)*100));let body='';
 if(r.phase==='warmup')body='<section class="show-stage warm"><div class="show-kicker">ПІДГОТОВКА / 5 ХВ</div><h2>Розігрійся.<br><em>Ми починаємо.</em></h2><div class="show-number"><span>РОЗМИНКА</span><strong id="flowWarmClock">'+trainingClock(Math.max(0,300000-trainingActiveMs()))+'</strong><small>легка ходьба + м’які рухи плечима й суглобами</small></div>'+trainingFigure('walk')+'<button class="show-continue" data-action="training-flow-next">Продовжити до вправи 01 <b>→</b></button><p class="show-under">Можеш перейти раніше або взяти більше часу. Таймер — орієнтир, не примус.</p></section>';
 if(r.phase==='exercise'){const prescription=item[1].replace(/^\d+(?:–\d+)?\s*×\s*/,''),seconds=target?Math.max(0,target*1000-(trainingActiveMs()-(r.stepActiveStart||0))):0,stage=trainingTimedStages(p)?r.index===0?'РОЗМИНКА':r.index===p.items.length-1?'СПОКІЙНЕ ЗАВЕРШЕННЯ':'ОСНОВНИЙ ВІДРІЗОК':'ВПРАВА';body='<section class="show-stage exercise"><div class="show-kicker">'+stage+' '+String(r.index+1).padStart(2,'0')+' / '+String(p.items.length).padStart(2,'0')+' · '+x.group+'</div><h2>'+x.name+'</h2><div class="show-metrics"><div class="show-main-metric"><span>'+(target?'ЧАС ВІДРІЗКА':'ПІДХІД')+'</span><strong id="'+(target?'flowStepClock':'flowSetNumber')+'">'+(target?trainingClock(seconds):String(r.set).padStart(2,'0')+' <i>/ '+String(count).padStart(2,'0')+'</i>')+'</strong></div><div class="show-reps"><span>'+(target?'ЗАВДАННЯ':'ПОВТОРІВ / ЧАС')+'</span><b>'+esc(prescription)+'</b></div></div><div class="show-model-wrap">'+trainingFigure(x.pose)+'<div class="show-model-tip">↗ '+esc(x.check)+'</div></div>'+(x.machine?'<details class="show-machine"><summary>◈ Як налаштувати тренажер?</summary><p>'+esc(x.machine)+'</p></details>':'')+'<div class="show-coach-note"><b>ЩО РОБИТИ</b><p>'+(target?'Тримай цей відрізок у комфортному темпі. '+esc(prescription)+'.':esc(x.cue))+'</p></div><button class="show-continue" data-action="training-flow-next">'+(target?'Відрізок виконано':'Підхід виконано')+' <b>✓</b></button><button class="show-skip" data-action="training-flow-skip">Пропустити вправу</button></section>';}
 if(r.phase==='rest')body='<section class="show-stage rest"><div class="show-kicker">ПАУЗА / ВІДНОВЛЕННЯ</div><h2>Перепочинь.<br><em>Ти в процесі.</em></h2><div class="show-rest-ring"><strong id="flowRestClock">'+trainingClock((r.restLeft||0)*1000)+'</strong><small>до наступного підходу</small></div><p>Можеш перейти раніше. Якщо треба довше — постав тренування на паузу.</p><button class="show-continue" data-action="training-flow-next">Я готова / готовий далі <b>→</b></button></section>';
 if(r.phase==='cooldown')body='<section class="show-stage cool"><div class="show-kicker">ФІНАЛЬНИЙ ЕТАП / 2 ХВ</div><h2>Поступово<br><em>сповільнись.</em></h2><div class="show-number"><span>СПОКІЙНИЙ РУХ</span><strong id="flowCoolClock">'+trainingClock(Math.max(0,120000-(trainingActiveMs()-(r.coolStart??trainingActiveMs()))))+'</strong><small>легка ходьба або рух у комфортному темпі</small></div>'+trainingFigure('walk')+'<button class="show-continue" data-action="training-flow-next">Завершити тренування <b>✓</b></button></section>';
 if(r.phase==='complete')body='<div class="flow-finish"><span>DAYMARK / ТРЕНУВАННЯ В ІСТОРІЇ</span><div class="flow-finish-star">🏆</div><h2>Ти зробила / зробив це!</h2><p>Запис у «Мій рух» збережено. Сьогодні в календарі — твоя позначка тренування.</p><div><b>'+r.savedMinutes+' хв</b><b>'+r.done+' підходів</b></div><button class="flow-primary" data-action="training-flow-calendar">Побачити календар ↗</button><button class="flow-secondary" data-action="training-flow-diary">Мій рух і запис</button><small>Денну ціль не закреслюємо автоматично: це твоє рішення.</small></div>';
 openModal('DAYMARK TRAINING / '+p.name.toUpperCase(),'<div class="show-shell"><div class="show-top"><span>🏃 '+esc(p.name)+'</span><b id="flowElapsed">'+trainingClock(trainingActiveMs())+'</b></div><div class="show-progress"><i style="width:'+progress+'%"></i></div><div class="show-progress-label"><span>'+(r.phase==='complete'?'ГОТОВО':r.phase==='warmup'?'РОЗМИНКА':r.phase==='rest'?'ВІДПОЧИНОК':r.phase==='cooldown'?'ЗАВЕРШЕННЯ':'ТРЕНУВАННЯ')+'</span><span>'+r.done+' / '+total+' підходів</span></div>'+body+(r.phase!=='complete'?'<button class="show-pause" data-action="training-flow-pause">Ⅱ Пауза · зберегти прогрес</button>':'')+'</div>');$('modal').classList.add('training-player-dialog','training-show-dialog');trainingSaveDraft();};

const previousFlowNext=trainingFlowNext;
trainingFlowNext=function(){const was=trainingRun?.phase;previousFlowNext();if(was==='exercise'&&trainingRun?.phase==='cooldown'){trainingRun.coolStart=trainingActiveMs();trainingFlowRender();}};
actions['training-flow-next']=()=>trainingFlowNext();
setInterval(()=>{if(!trainingRun||trainingRun.paused||!$('modal').open)return;const a=trainingActiveMs(),warm=$('flowWarmClock'),cool=$('flowCoolClock');if(warm)warm.textContent=trainingClock(Math.max(0,300000-a));if(cool)cool.textContent=trainingClock(Math.max(0,120000-(a-(trainingRun.coolStart||a))));},1000);
